<script>(function(){
function syncDestination(root){var s=root.querySelector('[data-waste-destination]'),f=root.querySelector('[data-waste-utilizer-field]');if(!s||!f)return;f.style.display=s.value==='utilizer'?'block':'none';var u=f.querySelector('select[name="utilizer_id"]');if(u)u.required=s.value==='utilizer';var blocked=s.value==='warehouse'||root.dataset.wasteGeneralForced==='1',general=root.querySelector('[data-waste-general-payment-block]'),notice=root.querySelector('[data-waste-general-disabled]');if(general){general.style.display=blocked?'none':'';general.querySelectorAll('input,select,textarea,button').forEach(function(control){control.disabled=blocked;});}if(notice)notice.style.display=blocked?'block':'none';}
function syncCost(root){
 var toggle=root.querySelector('[data-waste-no-markup]'),block=root.querySelector('.waste-carrier-payment-block');
 if(!toggle||!block)return;
 var rows=block.querySelector('[data-payment-container]'),button=block.querySelector('[data-add-payment-row]'),preview=block.querySelector('[data-waste-no-markup-preview]');
 if(rows){rows.style.display=toggle.checked?'none':'';rows.querySelectorAll('input,select,textarea,button').forEach(function(control){control.disabled=toggle.checked;});}
 if(button)button.disabled=toggle.checked;
 if(preview){preview.hidden=!toggle.checked;if(toggle.checked){
   var amounts=Array.from(root.querySelectorAll('[data-payment-container="customer_payments"] input[name$="[amount]"]')).map(function(input){return input.value.trim().replace(/\s/g,'').replace(',','.');});
   var valid=amounts.length>0&&amounts.every(function(v){return /^\d+(\.\d{1,2})?$/.test(v);});
   preview.querySelector('[data-waste-no-markup-total]').textContent=valid?(amounts.reduce(function(sum,v){return sum+Math.round(Number(v)*100);},0)/100).toLocaleString('ru-RU',{style:'currency',currency:'RUB',minimumFractionDigits:2,maximumFractionDigits:2}):'—';
 }}
}
function syncPlan(root){var m=root.querySelector('[data-waste-plan-mode]');if(!m)return;var e=root.querySelector('[data-waste-plan-exact]'),f=root.querySelector('[data-waste-plan-from]'),t=root.querySelector('[data-waste-plan-to]');var exact=m.value==='exact',range=m.value==='range';if(e){e.style.display=exact?'block':'none';e.required=exact;}if(f){f.style.display=range?'block':'none';f.required=range;}if(t){t.style.display=range?'block':'none';t.required=range;}}
async function preview(form){var r=form.querySelector('[data-waste-preview-result]'),b=form.querySelector('[data-waste-create-submit]');if(r)r.textContent='Проверка...';if(b)b.disabled=true;try{var x=await fetch('<?=app_url('/company/trips/departures/preview')?>',{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}),p=await x.json();if(!x.ok||!p.success){if(r)r.textContent=p.message||('Не найдены: '+(p.missing||[]).join(', ')+'; заняты: '+Object.keys(p.occupied||{}).join(', '));return;}if(r)r.textContent='Найдено '+p.found_count+'/'+p.input_count+', '+Number(p.total_mass_kg||0).toLocaleString('ru-RU')+' кг, конфликтов нет.';if(b)b.disabled=false;}catch(e){if(r)r.textContent='Ошибка проверки.';}}
async function loadModal(kind,id){var modal='waste-trip-view-modal',body=document.getElementById('waste-trip-view-body');body.innerHTML='<div class="modal-body">Загрузка...</div>';openModal(modal);try{var x=await fetch('<?=app_url('/company/trips/departures')?>/'+encodeURIComponent(id)+'/modal-'+kind,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}});body.innerHTML=await x.text();if(!x.ok)return;var title=body.querySelector('[data-waste-modal-title]');if(title)document.getElementById('waste-trip-view-title').textContent=title.dataset.wasteModalTitle;wireForm(body);paintStatusSelects(body);}catch(e){body.innerHTML='<div class="modal-body"><div class="notice warn">Не удалось загрузить рейс.</div></div>';}}
document.querySelectorAll('.waste-row[data-waste-view]').forEach(function(row){var open=function(){loadModal('view',row.dataset.wasteView)};row.addEventListener('dblclick',open);row.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});
document.addEventListener('click',function(e){var b=e.target.closest('[data-waste-open-edit]');if(b){loadModal('edit',b.dataset.wasteOpenEdit);return;}var c=e.target.closest('[data-waste-cancel-edit]');if(c)loadModal('view',c.dataset.wasteCancelEdit);});
function wireForm(root){var f=root.matches&&root.matches('form[data-linear-trip-form]')?root:root.querySelector('form[data-linear-trip-form]');if(!f)return;if(typeof window.initLinearTripForm==='function')window.initLinearTripForm(f);if(typeof window.initWasteExecutorSearch==='function')window.initWasteExecutorSearch(f);syncDestination(f);syncPlan(f);syncCost(f);var cost=f.querySelector('[data-waste-no-markup]');if(cost&&!cost.dataset.wasteBound){cost.dataset.wasteBound='1';cost.addEventListener('change',function(){syncCost(f)});f.addEventListener('input',function(e){if(e.target.matches('[data-payment-container="customer_payments"] input[name$="[amount]"]'))syncCost(f);});var customer=f.querySelector('[data-payment-container="customer_payments"]');if(customer)new MutationObserver(function(){syncCost(f)}).observe(customer,{childList:true,subtree:true});}var d=f.querySelector('[data-waste-destination]');if(d&&!d.dataset.wasteBound){d.dataset.wasteBound='1';d.addEventListener('change',function(){syncDestination(f)});}var p=f.querySelector('[data-waste-plan-mode]');if(p&&!p.dataset.wasteBound){p.dataset.wasteBound='1';p.addEventListener('change',function(){syncPlan(f)});}var v=f.querySelector('[data-waste-preview]');if(v&&!v.dataset.wasteBound){v.dataset.wasteBound='1';v.addEventListener('click',function(){preview(f)});}var ids=f.querySelector('[data-waste-request-ids]');if(ids&&!ids.dataset.wasteBound){ids.dataset.wasteBound='1';ids.addEventListener('input',function(){var b=f.querySelector('[data-waste-create-submit]');if(b)b.disabled=true;});}}
document.querySelectorAll('form').forEach(wireForm);
function paintStatusSelects(root){root.querySelectorAll('select[name="status"]').forEach(function(select){select.dataset.wasteStatus=select.value;});}
paintStatusSelects(document);
document.addEventListener('change',function(event){if(event.target.matches('select[name="status"]'))event.target.dataset.wasteStatus=event.target.value;});
var wasteFilter=document.querySelector('[data-waste-filter]');if(wasteFilter){var search=wasteFilter.querySelector('[name="q"]'),timer,initial=new URLSearchParams(location.search),defaults={company:'',status:'',manager:'',sort:'status',q:''},registryRoot=wasteFilter.closest('[data-registry-id]');var changed=function(){return Object.keys(defaults).some(function(name){var field=wasteFilter.elements.namedItem(name);return field&&field.value!==(initial.get(name)??defaults[name]);});};var submitIfChanged=function(){if(changed())wasteFilter.requestSubmit();};var schedule=function(delay){if(registryRoot?.dataset.registryHydrating==='true')return;clearTimeout(timer);timer=setTimeout(submitIfChanged,delay);};registryRoot?.addEventListener('registry:hydrated',function(){schedule(0);});wasteFilter.querySelectorAll('select').forEach(function(select){select.addEventListener('change',function(){schedule(0);});});if(search){search.addEventListener('input',function(){schedule(400);});search.addEventListener('keydown',function(event){if(event.key==='Enter'){clearTimeout(timer);}});}}
var statusNav=document.querySelector('[data-waste-status-tabs]');if(statusNav&&wasteFilter){var statusSelect=wasteFilter.querySelector('select[name="status"]'),statusButtons=[...statusNav.querySelectorAll('button[data-status]')],markStatus=function(value){statusButtons.forEach(function(tab){tab.setAttribute('aria-pressed',tab.dataset.status===value?'true':'false');});};statusSelect.addEventListener('change',function(){markStatus(statusSelect.value);});statusButtons.forEach(function(button){button.addEventListener('click',function(){markStatus(button.dataset.status);if(statusSelect.value===button.dataset.status)return;statusSelect.value=button.dataset.status;statusSelect.dispatchEvent(new Event('change',{bubbles:true}));});});statusNav.addEventListener('keydown',function(event){var index=statusButtons.indexOf(document.activeElement),next=event.key==='ArrowRight'?index+1:event.key==='ArrowLeft'?index-1:event.key==='Home'?0:event.key==='End'?statusButtons.length-1:-1;if(index<0||next<0)return;event.preventDefault();statusButtons[(next+statusButtons.length)%statusButtons.length].focus();});requestAnimationFrame(function(){var active=statusNav.querySelector('[aria-pressed="true"]');if(!active)return;var strip=statusNav.getBoundingClientRect(),tab=active.getBoundingClientRect();if(tab.left<strip.left)statusNav.scrollLeft+=tab.left-strip.left;if(tab.right>strip.right)statusNav.scrollLeft+=tab.right-strip.right;});}
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-linear-trip-form]').forEach(wireForm);});
<?php if($showCreateModal):?>openModal('waste-trip-create-modal');<?php endif;?>
<?php if($openTripId>0):?>loadModal('view',<?=$openTripId?>);<?php endif;?>
<?php if($openEditId>0):?>loadModal('edit',<?=$openEditId?>);<?php endif;?>
})();</script>
